entries[251783] = { ["name"] = "Lost Idol of the Hash'ey", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Speed\nEquip: Your attacks and abilities have a low chance to beckon a random Loa spirit to your side, increasing your combat capabilities for 30 sec. (5s cooldown)\nSell Price:" }
entries[251784] = { ["name"] = "Sylvan Wakrapuku", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Intellect]\nEquip: Your harmful spells and ranged abilities have a chance to call forth Loa aspects to bombard your target three times, each time dealing ( 1 * 591 ) Physical damage split between all nearby enemies.\nSell Price:" }
entries[251785] = { ["name"] = "Void-Reaper's Libram", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Intellect]\nEquip: Your harmful spells and abilities have a chance to brand your target with sacred text dealing ( 42 * 30) Holy damage over 30 sec.\n\nRebranding an enemy ignites the text, granting you 21 Critical Strike for 15 sec and immediately dealing all remaining damage. (5s cooldown)\nSell Price:" }
entries[251786] = { ["name"] = "Ever-Collapsing Void Fissure", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nUse: Hold the fissure open causing time to distort itself reducing your movement speed by 50% while increasing your Haste by 26 each second over 10 sec. (2 Min Cooldown)\nSell Price:" }
entries[251787] = { ["name"] = "Sealed Chaos Urn", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength or Intellect]\nUse: Unseal the urn causing the void within to pour out and engulf you for 20 sec, increasing all secondary stats by 43 .\n\nAs the void dissipates, you become horrified for 5 sec. Killing an enemy while engulfed prevents this effect from occurring. (2 Min Cooldown)\nSell Price:" }
entries[251788] = { ["name"] = "Gift of Light", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nEquip: Your healing spells and abilities have a chance to increase your Mastery by 77 for 10 sec.\nIf this occurs while healing an ally below 40% health, grant double the mastery.\n\nCan only occur once every 1 min.\nSell Price:" }
entries[251789] = { ["name"] = "Consecrated Chalice", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nEquip: Your healing spells and abilities have a high chance to fill the chalice with Hope, drop by drop, up to 15 times.\nUse: Empty the chalice upon an ally granting them ( 1 * 223 ) absorb for each drop spilled for 20 sec. (20 Sec Cooldown)\nSell Price:" }
entries[251790] = { ["name"] = "Desecrated Chalice", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\nEquip: Taking damage has a high chance to fill the chalice with Despair, drop by drop, up to 10 times. Once full, the chalice spills, blanketing the ground beneath you in a dark mire dealing 364 Void damage each second split between enemies inside for 10 sec while granting you 110 versatility. (1s cooldown)\nSell Price:" }
entries[251791] = { ["name"] = "Holy Retributor's Order", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\nEquip: The light blesses your weapon granting your attacks a chance to deal 315 additional Holy damage and heal you for 2896 health.\nSell Price:" }
entries[251792] = { ["name"] = "Glorious Crusader's Keepsake", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength or Intellect]\nEquip: During combat you have a chance to become consumed by Fanatical Inspiration, increasing your highest secondary by 56 for 15 sec.\n\nParty members also equipped with the keepsake have their lowest secondary increased by 6 for 15 sec.\nSell Price:" }
entries[251793] = { ["name"] = "Endosymbiotic Mycelium", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength or Intellect]\nUse: Spores surrounds you, making you gain [A] shield for [B]sec. Upon expiration gain [C] leech for [D] sec.\nSell Price:" }
entries[251794] = { ["name"] = "Gris-gris of Confidence", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength or Intellect]\nEquip: You feel confident that you can predict movements ahead of time, making you gain [A] leech. Each time you are hit, you have a chance of losing [B] leech until reaching [C] leech. Killing an enemy resets your leech.\nSell Price:" }
