entries[252011] = { ["name"] = "Brilliant Petalwing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This beast glows with a radiance no void could suppress.\"\nAchievement:\nLight Up the Night\nCategory:\nMidnight" }
entries[252012] = { ["name"] = "Vibrant Petalwing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Filling the skies of Harandar with a striking pink hue, the Vibrant Petalwing attained its noteworthy pigment through the nectar of various flora it consumes.\"\nDrop:\nHarandar Rare Creatures" }
entries[252014] = { ["name"] = "Cerulean Sporeglider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 19 with the Hara'ti.\n\n\"This sporeglider likes to gently nuzzle its riders.\"\nVendor:\nNaynar\nZone:\nHarandar\nCost:\n8000" }
entries[252017] = { ["name"] = "Ruddy Sporeglider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This sporeglider derived its striking hue from the unique fungus growing around Teldrassil's roots.\"\nTreasure:\nPeculiar Cauldron\nZone:\nHarandar" }
entries[252018] = { ["name"] = "Pristine Lightbound Crystal", ["text"] = "Binds when picked up\nEquip: Grants 3 additional ranks of Light's Vengeance .\n\nLight's Vengeance\nYour spells and abilities have a chance to manifest holy light, healing a nearby injured ally for [(242% Attack/Spell Power)] and dealing [(200% Attack/Spell Power)] Holy damage to enemies within 6 yards of them.\n\nHealing and damage are doubled while Lightforged .\nRequires level 10 to 90 ( 90)" }
