entries[252418] = { ["name"] = "Solar Core Igniter", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\nUse: Ignite the Solar Core within you for 15 sec, forming a radiant shield that absorbs 50% of incoming damage, up to 828 . Gain up to 24 Versatility for 10 sec if the shield expires, based on its remaining power. (1 Min, 30 Sec Cooldown)\nSell Price:" }
