entries[252679] = { ["name"] = "Mechanical Prototype Panther MK-0", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"When Gadgetzan citizens pried open Gazlowe palace's underground lab, caged beasts' roars were suffocating. Undermine tech fused combat modules onto these panthers, granting superhuman strength and speed. Rustbolt engineers reprogrammed them exclusively for warriors campaigning in K'aresh. Remember to swap modules at the Morphing Forum before deployment.\"\nIn-Game Shop" }
entries[252681] = { ["name"] = "Steel Prototype Panther MK-0", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The first Steel Horde soldiers crossing the Dark Portal captured a ferocious nightsaber. Blackrock artisans armed it with magma armor, transforming it into a combat weapon. Warriors may customize its parts at the Morphing Forum to suit their fighting style and dominate the battlefield.\"\nIn-Game Shop" }
