entries[252950] = { ["name"] = "Starspark Netherdrake", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses this flying mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"After flying you to the ends of Outland and beyond, the netherwing drake was eventually drawn to the blue skies of Azeroth as well.\"\nPromotion:\nBurning Crusade Classic" }
entries[252951] = { ["name"] = "Set Keystone Map: Maisara Caverns", ["text"] = "Duration: 12 hrs (real time)\nUse: Set the dungeon map of a Mythic Keystone to Maisara Caverns.\nSell Price:" }
