entries[252954] = { ["name"] = "Felscorned Reins of the Vilebrood Vanquisher", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Death Knights can ride this mount.\nSummons and dismisses your Felscorned Vilebrood Vanquisher. This mount is only available to Death Knights.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This flying amalgamation of the forces of death and fel pierces the skies with a bone-chilling screech.\"\nWorld Event:\nWoW Remix: Legion" }
entries[252956] = { ["name"] = "Aln-Bound Essence", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Versatility\nEquip: Your spells and abilities have a chance to awaken the unbound essence of Aln, increasing your Primary Stat by ( 6 * 8). This power, drawn from half-formed dreams and mists, fades with each ability used or after 12 sec.\nSell Price:" }
entries[252957] = { ["name"] = "Tangle of Vibrant Vines", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Critical Strike\nEquip: Your spells and abilities have a chance to unleash vibrant vines that surge toward your target. Enemies struck take ( 176 * 5) Nature damage over 8 sec. Allies are wrapped in protective flora, absorbing up to 7180 damage over 8 sec.\nSell Price:" }
