entries[253013] = { ["name"] = "Slayer's Reins of the Felscorned Shrieker", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Demon Hunters can ride this mount.\nSummons and dismisses your Slayer's Felscorned Shrieker. This mount is only available to Demon Hunters.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Torn from the heavens by only the most cunning of Demon Hunters.\"\nWorld Event:\nWoW Remix: Legion" }
