entries[253024] = { ["name"] = "Feldruid's Scornwing Idol", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMount\n(Account-wide)\nUse: Unlocks the Scornwing Flight Form in the Barber Shop. Only Druids can use this shapeshift form.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\"Unlocks the Scornwing Flight Form option in the Barber Shop. Only Druids can use this shapeshift form.\"" }
entries[253025] = { ["name"] = "Reins of the Felscorned Wolfhawk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Hunters can ride this mount.\nSummons and dismisses your Felscorned Wolfhawk. This mount is only available to Hunters.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Scarred by the war across the Broken Isles, this Wolfhawk deserves a good home.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253026] = { ["name"] = "Archmage's Felscorned Disc", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Mages can ride this mount.\nSummons and dismisses your Archmage's Felscorned Disc. This mount is only available to Mages.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Some mages say fel magics are \"volatile\" or \"corruptive\" or \"forbidden\". Some mages are wrong.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253027] = { ["name"] = "Felscorned Grandmaster's Bell", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Monks can ride this mount.\nSummons and dismisses your Felscorned Grandmaster's Companion. This mount is only available to Monks.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A twisted visage of a beloved companion.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253028] = { ["name"] = "Reins of the Highlord's Felscorned Charger", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Paladins can ride this mount.\nSummons and dismisses your Felscorned Highlord's Charger. This mount is only available to Paladins.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This horse has been irreversibly scarred by the Legion's corrupt magics.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253029] = { ["name"] = "Felscorned Seeker's Whistle", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Priests can ride this mount.\nSummons and dismisses your High Priest's Felscorned Seeker. This mount is only available to Priests.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This fel-infused feathered friend flaps its wings at a frenetic pace to remain far above the frenzy below.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253030] = { ["name"] = "Shadowblade's Reins of Felscorned Portent", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Rogues can ride this mount.\nSummons and dismisses your Shadowblade's Felscorned Omen. This mount is only available to Rogues.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Your enemies will know fear before their end.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253031] = { ["name"] = "Felscorned Tempest Totem", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Shamans can ride this mount.\nSummons and dismisses your Farseer's Felscorned Tempest. This mount is only available to Shamans.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Fel flavored fury.\"\nWorld Event:\nWoW Remix: Legion" }
entries[253032] = { ["name"] = "Felscorned Reins of the Netherlord's Dreadsteed", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Only Warlocks can ride this mount.\nSummons and dismisses your Felscorned Netherlord's Dreadsteed. This mount is only available to Warlocks.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Simply oozing with potential.\"\nWorld Event:\nWoW Remix: Legion" }
