entries[253222] = { ["name"] = "Corrupted Thorn of the Dream", ["text"] = "Legion Remix: Skies of Fire\nBinds when picked up\nUse: Combine 10 of these to create an item belonging to the Emerald Nightmare.\nRequires level 10 to 90 ( 90)\n\"In the Emerald Nightmare, even a thorn can blossom into something potent and deadly.\"" }
entries[253223] = { ["name"] = "Fractal Felshard", ["text"] = "Legion Remix: Legionfall\nBinds when picked up\nUse: Combine 10 of these to create an item belonging to Tomb of Sargeras.\nRequires level 10 to 90 ( 90)\n\"The Deceiver's might is so great that even a drop of his blood, cooled and crystallized to a sliver, contains near-infinite potential.\"" }
entries[253224] = { ["name"] = "Mote of a Broken Time", ["text"] = "Legion Remix\nBinds when picked up\nUse: Combine 10 of these to create an item belonging to an available raid in Legion: Remix.\nRequires level 10 to 90 ( 90)\n\"A prismatic shard that resonates with this fractured timeline. Simultaneously it takes shape as a corrupted thorn, a warlock's gem, a fel-bright sliver, or an echo of death.\"" }
