entries[253573] = { ["name"] = "Cobalt Phase-Hunter", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Due to the otherworldly energies that irradiated Draenor, these creatures can shift through space at will. As such, they are rarely seen... until it is too late.\"\nPromotion:\nBurning Crusade Classic" }
